define(["core/ajax","core/templates","core/notification"],function(Ajax,Templates,Notification){const init=function(flexbookId){const form=document.querySelector("[data-region='flexbook-search']");if(!form){return}form.addEventListener("submit",function(event){event.preventDefault();const query=form.querySelector("input").value.trim();if(query.length<2){return}Ajax.call([{methodname:"mod_flexbook_search_contents",args:{flexbookid:flexbookId,query:query}}])[0].then(function(results){return Templates.renderForPromise("mod_flexbook/search_results",{results:results})}).then(function(result){Templates.replaceNodeContents(form.querySelector("[data-region='search-results']"),result.html,result.js);return true}).catch(Notification.exception)})};return{init:init}});